import { setupRerender, act } from 'preact/test-utils';
import { createElement, render } from 'preact';
import { setupScratch, teardown } from '../../../test/_util/helpers';
import { useState } from 'preact/hooks';

/** @jsx createElement */

describe('tmp repro #3739', () => {
	/** @type {HTMLDivElement} */
	let scratch;

	/** @type {() => void} */
	let rerender;

	beforeEach(() => {
		scratch = setupScratch();
		rerender = setupRerender();
	});

	afterEach(() => {
		teardown(scratch);
	});

	it('should re-render when state is reverted and props change in same tick', () => {
		let setActive;
		let updateParent;
		const calls = [];

		function Child({ labelText }) {
			const [active, _setActive] = useState(false);
			setActive = _setActive;
			calls.push(`active=${active} label=${labelText}`);
			return null;
		}

		function Parent() {
			const [value, setValue] = useState(0);
			updateParent = () => setValue(v => v + 1);
			return <Child labelText={'value=' + value} />;
		}

		render(<Parent />, scratch);
		expect(calls).to.deep.equal(['active=false label=value=0']);
		calls.length = 0;

		// set state then undo it on the same tick, plus a prop change
		act(() => {
			setActive(true);
			setActive(false);
			updateParent();
		});

		expect(calls).to.deep.equal(['active=false label=value=1']);

		calls.length = 0;
		// a new prop change on a later tick still works
		act(() => updateParent());
		expect(calls).to.deep.equal(['active=false label=value=2']);
	});

	it('should still bail out when state is reverted and props unchanged', () => {
		let setActive;
		const calls = [];

		function Child() {
			const [active, _setActive] = useState(false);
			setActive = _setActive;
			calls.push(`active=${active}`);
			return null;
		}

		function Parent({ children }) {
			return children;
		}

		render(<Parent><Child /></Parent>, scratch);
		expect(calls).to.deep.equal(['active=false']);
		calls.length = 0;

		act(() => {
			setActive(true);
			setActive(false);
		});

		expect(calls).to.deep.equal([]);
	});
});

